insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-pierogi-leniwe', 'de', 'Pierogi leniwe', 'pierogi-leniwe', 'Pierogi leniwe sind weiche Klößchen aus Twaróg, Ei und Mehl, die geschnitten statt gefaltet werden, dadurch milder und schneller fertig als klassische gefüllte Pierogi oder die kartoffelbasierten Kopytka und Kluski śląskie.', '[{"text":"Twaróg gut abtropfen lassen und mit Ei, Mehl und einer Prise Salz zu einem weichen, aber formbaren Teig verkneten.","tip":"Je feuchter der Twaróg, desto mehr Mehl braucht der Teig danach, drücke ihn deshalb vorher in einem Tuch gut aus, sonst wird die Masse am Ende klebrig."},{"text":"Den Teig zu einer Rolle mit etwa drei Zentimetern Durchmesser formen und schräg in mundgerechte Stücke schneiden.","tip":"Vor dem Schneiden lässt sich mit der stumpfen Messerseite ein feines Gittermuster in die Rolle drücken, darin hält später mehr Butter und Brösel."},{"text":"Die Klößchen in leicht siedendem Salzwasser garen, bis sie an die Oberfläche steigen, das dauert nur wenige Minuten.","tip":"Das Wasser darf nur sanft köcheln, in sprudelndem Wasser brechen die weichen Klößchen an den Kanten leicht auf."},{"text":"Mit in Butter gerösteten Semmelbröseln, Zucker oder saurer Sahne servieren.","tip":"Gefüllte Obst-Knödel wie die [Knedle ze śliwkami](/de/rezepte/knedle-sliwki) gehören zu einer ganz anderen Teigfamilie, einen Überblick über alle Formen gibt der [Pierogi-Guide](/de/blog/pierogi-guide)."}]'::jsonb, 'Pierogi leniwe, mild, weich und ganz ohne den Aufwand des Faltens. Pierogi leniwe verdanken ihren Namen nicht dem Kochvorgang, sondern der eingesparten Arbeit: Twaróg, Mehl und Ei sind dieselben Zutaten wie bei klassischen gefüllten Käse-Pierogi, nur knetet hier niemand Teig getrennt, rollt ihn aus, streicht Füllung darauf und kneift jeden einzelnen Rand zusammen. Stattdessen wird alles zu einer Masse verknetet, zu einer Rolle geformt und geschnitten, daher leniwe, also faul. Rezepte dafür sind in polnischen Kochbüchern schon seit dem 18. Jahrhundert belegt, richtig populär wurden sie aber durch die Milchbars, die sogenannten bary mleczne, 1896 von Stanisław Dłużewski gegründet und in der PRL-Zeit zu preiswerten Kantinen mit einfacher, milch- und eibasierter Küche geworden. Leniwe sind dabei keine gefalteten Pierogi wie [Pierogi Ruskie](/de/rezepte/pierogi/ruskie), sie enthalten keine Kartoffel wie [Kopytka](/de/rezepte/kopytka) und keine Kartoffelstärke wie [Kluski śląskie](/de/rezepte/kluski-slaskie). Die breite Teigfamilie ordnet der [Pierogi-Guide](/de/blog/pierogi-guide), gefüllte Obst-Knödel sind [Knedle ze śliwkami](/de/rezepte/knedle-sliwki), nicht diese Seite. Heiße Nudeln mit Twaróg-Sauce darüber sind wiederum ein anderer Teller: [Makaron z serem](/de/rezepte/makaron-z-serem).

## Einkaufen und kochen

Twaróg oder gut abgetropfter Speisequark, Mehl und Ei sowie Butter und Semmelbrösel reichen für dieses Rezept aus. Konsistenz und Einkauf in Deutschland erklärt der [Twaróg-Guide](/de/blog/twarog-deutschland), die Route über den [Polenladen](/de/blog/polenladen-einkaufen) lohnt sich oft, weil der Quark dort meist trockener und dadurch ergiebiger ist.

Der Teig soll weich, aber formbar bleiben, zu viel Mehl macht die Klößchen gummiartig statt zart. Koche sie in leicht siedendem, nicht sprudelndem Wasser und nimm sie heraus, sobald sie aufschwimmen. Das ist kein Nudelkochen mit Quark-Sauce, das wäre [Makaron z serem](/de/rezepte/makaron-z-serem).

Für viele Kinder in Deutschland sind Leniwe das erste Pierogi-Erlebnis, weil niemand falten muss und das Ergebnis trotzdem vertraut schmeckt. Wer später Obst einpacken möchte, wechselt zu den [Knedle](/de/rezepte/knedle-sliwki), wer ganz auf Kloßteig verzichten will, landet bei [Makaron z serem](/de/rezepte/makaron-z-serem).

## Am Tisch

Klassisch mit in Butter geröstetem Semmelbrösel und Zucker oder mit Śmietana, mehr zur Wahl zwischen beiden liefert [Śmietana vs. Schmand](/de/blog/smietana-schmand). Auch herzhaft mit Salz und Dill schmecken sie gut. Als Sonntags-Dessert passen sie neben das [Sonntagsessen](/de/blog/sonntagsessen-polnisch).

Zu viel Mehl, zu starkes Kochen und zu nasser Quark sind die klassischen Fehler. Tropfe den Twaróg gut ab und bleibe ruhig am Topf, und vermische die Technik nicht mit gefalteten [Pierogi Ruskie](/de/rezepte/pierogi/ruskie), mit Knedle oder mit Nudeln plus Quark-Sauce wie bei [Makaron z serem](/de/rezepte/makaron-z-serem).

Mit etwas Kartoffelanteil werden Leniwe fester, mit mehr Zucker süßer und milder. Nicht verwechseln mit gefalteten [Pierogi Ruskie](/de/rezepte/pierogi/ruskie). Eine süße, gefüllte Nachbarschaft bilden die [Knedle mit Pflaumen](/de/rezepte/knedle-sliwki), ein Pasta-Comfort ganz ohne Kloßteig ist [Makaron z serem](/de/rezepte/makaron-z-serem).', 'Pierogi leniwe Rezept | Twaróg-Klößchen ohne Falten | Alemniam', 'Pierogi leniwe: weiche Twaróg-Klößchen, geschnitten statt gefaltet. Schnelles Rezept mit Tipps zu Teig, Garzeit und Servieren, zweisprachig.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-pierogi-leniwe', 'pl', 'Pierogi leniwe', 'pierogi-leniwe', 'Pierogi leniwe to miękkie kluseczki z twarogu, jajka i mąki, które się kroi, a nie lepi, dlatego są łagodniejsze i szybsze niż sklejane pierogi czy ziemniaczane kopytka i kluski śląskie.', '[{"text":"Dobrze odciśnięty twaróg zagnieć z jajkiem, mąką i szczyptą soli na miękkie, ale formowalne ciasto.","tip":"Im bardziej wilgotny twaróg, tym więcej mąki potrzeba później, więc najpierw odciśnij go w ściereczce, inaczej masa wyjdzie kleista."},{"text":"Uformuj wałek o średnicy około trzech centymetrów i pokrój go skośnie na kawałki wielkości kęsa.","tip":"Przed krojeniem można tępą stroną noża odbić na wałku siateczkę, dzięki niej kluseczki lepiej trzymają potem masło i bułkę tartą."},{"text":"Gotuj kluseczki w lekko wrzącej osolonej wodzie, aż wypłyną na powierzchnię, to zajmuje tylko kilka minut.","tip":"Woda ma tylko lekko bulgotać, w gwałtownie wrzącej wodzie miękkie kluseczki łatwo rozpadają się na brzegach."},{"text":"Podawaj z bułką tartą podsmażoną na maśle, cukrem albo śmietaną.","tip":"Nadziewane knedle owocowe, jak [knedle ze śliwkami](/pl/rezepte/knedle-sliwki), to zupełnie inna rodzina ciast, przegląd wszystkich form daje [przewodnik po pierogach](/pl/blog/przewodnik-pierogi)."}]'::jsonb, 'Pierogi leniwe, łagodne, miękkie i bez trudu związanego z lepieniem. Pierogi leniwe zawdzięczają nazwę nie sposobowi gotowania, a zaoszczędzonej pracy: twaróg, mąka i jajko to te same składniki, co w klasycznych pierogach z serem, tylko że nikt nie wałkuje ciasta osobno, nie nakłada na nie farszu i nie zlepia każdego brzegu z osobna. Wszystko miesza się razem w jedną masę, formuje w wałek i kroi, stąd leniwe. Przepisy na nie są potwierdzone w polskich książkach kucharskich już od XVIII wieku, ale naprawdę rozpowszechniły się dzięki barom mlecznym, założonym w 1896 roku przez Stanisława Dłużewskiego i przekształconym w czasach PRL w tanie jadłodajnie z prostą kuchnią na bazie mleka i jajek. Leniwe to przy tym nie sklejane pierogi jak [ruskie](/pl/rezepte/pierogi/ruskie), nie ma w nich ziemniaka jak w [kopytkach](/pl/rezepte/kopytka) i nie ma skrobi ziemniaczanej jak w [kluskach śląskich](/pl/rezepte/kluski-slaskie). Rodzinę ciast porządkuje [przewodnik po pierogach](/pl/blog/przewodnik-pierogi), knedle owocowe to [knedle ze śliwkami](/pl/rezepte/knedle-sliwki), nie ta strona. Gorący makaron z sosem twarogowym to inny talerz: [makaron z serem](/pl/rezepte/makaron-z-serem).

## Zakupy i gotowanie

Twaróg lub dobrze odsączony Quark, mąka i jajko oraz masło i bułka tarta wystarczą na to danie. Konsystencję i zakupy w Niemczech opisuje [przewodnik po twarogu](/pl/blog/twarog-w-niemczech), trasa przez [sklep polski](/pl/blog/sklep-polski-zakupy) często się opłaca, bo tamtejszy twaróg jest zwykle suchszy i dzięki temu wydajniejszy.

Ciasto ma zostać miękkie, ale formowalne, za dużo mąki robi kluseczki gumowate, a nie delikatne. Gotuj je w lekko wrzącej, nie burzącej wodzie i wyjmuj, gdy wypłyną. To nie gotowanie makaronu z sosem twarogowym, tym byłby [makaron z serem](/pl/rezepte/makaron-z-serem).

Dla wielu dzieci w Niemczech leniwe są pierwszym doświadczeniem pierogów, bo nikt nie musi lepić, a wynik smakuje mimo to swojsko. Kto później chce owoc w środku, przechodzi do [knedli](/pl/rezepte/knedle-sliwki), a kto zupełnie nie chce ciasta klusek, trafia do [makaronu z serem](/pl/rezepte/makaron-z-serem).

## Przy stole

Klasycznie z bułką tartą podsmażoną na maśle i cukrem albo ze śmietaną, więcej o wyborze między nimi mówi [śmietana czy Schmand](/pl/blog/smietana-czy-schmand). Dobrze smakują też wytrawnie, z solą i koperkiem. Jako niedzielny deser pasują obok [obiadu niedzielnego](/pl/blog/obiad-niedzielny).

Za dużo mąki, zbyt gwałtowne gotowanie i za mokry twaróg to klasyczne błędy. Dobrze odsącz twaróg i zachowaj spokój przy garnku, i nie mieszaj tej techniki ze sklejanymi [ruskimi](/pl/rezepte/pierogi/ruskie), z knedlami ani z makaronem z sosem twarogowym jak [makaron z serem](/pl/rezepte/makaron-z-serem).

Z udziałem ziemniaka leniwe stają się bardziej zwarte, z większą ilością cukru słodsze i łagodniejsze. Nie mylić ze sklejanymi [ruskimi](/pl/rezepte/pierogi/ruskie). Słodkie, nadziewane sąsiedztwo tworzą [knedle ze śliwkami](/pl/rezepte/knedle-sliwki), a comfort food bez ciasta klusek to [makaron z serem](/pl/rezepte/makaron-z-serem).', 'Pierogi leniwe przepis | Kluseczki z twarogu bez lepienia | Alemniam', 'Pierogi leniwe: miękkie kluseczki z twarogu, krojone, nie lepione. Przepis z poradami o cieście, gotowaniu i podawaniu.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
